import java.util.ArrayList;
import java.util.List;

public class TopThreeTrackerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String names(List<Runner> runners) {
        if (runners == null) {
            return "<null>";
        }
        List<String> out = new ArrayList<>();
        for (Runner r : runners) {
            out.add(r.name());
        }
        return out.toString();
    }

    public static void main(String[] args) {
        TopThreeTracker t = new TopThreeTracker();
        check("fastest() before anything", "", t.fastest());
        check("size() before anything", 0, t.size());
        check("best() before anything", "[]", names(t.best()));

        t.offer(new Runner("dana", 40));
        t.offer(new Runner("ben", 25));
        check("after two offers", "[ben, dana]", names(t.best()));
        check("fastest() after two offers", "ben", t.fastest());

        t.offer(new Runner("cara", 33));
        t.offer(new Runner("eli", 90));
        check("a slow fourth runner is dropped", "[ben, cara, dana]", names(t.best()));
        check("size() is capped at 3", 3, t.size());

        t.offer(new Runner("finn", 10));
        check("a fast runner pushes the slowest out", "[finn, ben, cara]", names(t.best()));
        check("fastest() after finn", "finn", t.fastest());

        TopThreeTracker ties = new TopThreeTracker();
        ties.offer(new Runner("zoe", 20));
        ties.offer(new Runner("amy", 20));
        ties.offer(new Runner("mia", 20));
        check("equal times break by name", "[amy, mia, zoe]", names(ties.best()));

        List<Runner> snapshot = ties.best();
        if (snapshot != null) {
            snapshot.clear();
        }
        check("best() returns a copy", 3, ties.size());
        check("best() still intact", "[amy, mia, zoe]", names(ties.best()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
