import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** A race result. Provided -- do not edit. */
record Runner(String name, int seconds) { }

/**
 * TASK: Build a small stateful class that keeps only the three FASTEST runners
 * it has been shown, in order, no matter how many are offered.
 *
 * The ordering rule, used everywhere in this class:
 *     fewest seconds first, ties broken by name alphabetically.
 * Build it once as a Comparator field with
 *     Comparator.comparingInt(Runner::seconds).thenComparing(Runner::name)
 *
 * offer(runner): remember the runner, then drop anything past the best three.
 *   A simple way: add to the internal list, sort it with the comparator, and
 *   remove the last element while size() > 3.
 * best():  the kept runners, fastest first -- a COPY, so the caller cannot
 *   reach into this object's list.
 * size():  how many runners are currently kept (never more than 3).
 * fastest(): the name of the leader, or "" when nothing has been offered.
 *
 * INVARIANT: after every offer, best() is sorted and holds at most 3 runners.
 */
public class TopThreeTracker {

    private final List<Runner> kept = new ArrayList<>();
    private final Comparator<Runner> order = Comparator.comparingInt(Runner::seconds).thenComparing(Runner::name);

    public void offer(Runner runner) {
        kept.add(runner);
        kept.sort(order);
        while (kept.size() > 3) {
            kept.remove(kept.size() - 1);
        }
    }

    public List<Runner> best() {
        return new ArrayList<>(kept);
    }

    public int size() {
        return kept.size();
    }

    public String fastest() {
        return kept.isEmpty() ? "" : kept.get(0).name();
    }
}
